import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.update

data class Ui(val items: List<String>, val loading: Boolean)

fun main() {
    val state = MutableStateFlow(Ui(emptyList(), true))
    state.update { it.copy(items = it.items + "хлеб") }
    state.update { it.copy(items = it.items + "сыр", loading = false) }
    val old = state.value
    state.update { it.copy(items = emptyList()) }
    println(old.items)
    println(state.value.items.size)
    println(state.value.loading)
}
